<template>
  <el-dialog
    title="开场设置"
    :visible.sync="dialogVisible"
    v-if="dialogVisible"
    @before-close="onBeforeClose"
    width="1050px"
  >
    <el-tabs type="border-card" v-model="tabId">
      <el-tab-pane label="开场效果" name="begin_style">
        <el-form
          :model="styleForm"
          :label-width="formLabelWidth"
          ref="beginstyleForm"
          class="setting-pro-form-inline"
        >
          <el-form-item label="小行星入场动画" style="display: inline-block;">
            <el-switch
              v-model="styleForm.use_intro_entrance"
              active-color="#13ce66"
              inactive-color="#ff4949"
              :active-value="1"
              :inactive-value="0"
            >
            </el-switch>
          </el-form-item>
          <el-form-item label="入场后是否旋转" style="display: inline-block;">
            <el-switch
              v-model="styleForm.intro_auto_rate"
              active-color="#13ce66"
              inactive-color="#ff4949"
              :active-value="1"
              :inactive-value="0"
            >
            </el-switch>
          </el-form-item>
          <el-form-item label="提示图片">
            <vr-upload
              ref="tipImgUploader"
              key="tipImgUploader"
              uploadClass="upload-img-container"
              tip="建议尺寸：300 X 300"
              listType
              :showDelAction="true"
              :cropImg="false"
              :autoUpload="true"
              @onSuccess="onTipImgUploadSuccess"
              @onClearFile="onTipImgClearLogoFile"
            />
          </el-form-item>
          <el-form-item label="提示显示时间">
            <el-slider
              v-model="styleForm.show_time"
              class="show-time-slider"
              :marks="{ 0: '0s', 10: '10s' }"
              :max="10"
            ></el-slider>
          </el-form-item>
          <el-form-item>
            <el-button type="primary" @click="onSaveBeginTip"
              >保存并继续</el-button
            >
            <el-button type="primary" @click="onSaveAndCloseBeginTip"
              >保存并关闭</el-button
            >
          </el-form-item>
        </el-form>
      </el-tab-pane>
      <el-tab-pane label="开场封面" name="begin_cover">
        <el-form
          :model="coverForm"
          :inline="true"
          :label-width="formLabelWidth"
          ref="beginCoverForm"
          class="setting-pro-form-inline"
        >
          <el-form-item label="桌面端(默认全屏显示在页面)">
            <vr-upload
              ref="coverPcImgUploader"
              key="coverPcImgUploader"
              uploadClass="upload-img-container"
              tip="建议尺寸：1000 X 650"
              listType
              :showDelAction="true"
              :cropImg="false"
              :cropFixed="false"
              cropDialogTop="5vh"
              :cropDialogModal="false"
              :autoCropWidth="1000"
              :autoCropHeight="650"
              :autoUpload="true"
              @onSuccess="onCoverPcUploadSuccess"
              @onClearFile="onCoverPcClearLogoFile"
            />
          </el-form-item>
          <el-form-item label="移动端(默认全屏显示在页面)">
            <vr-upload
              ref="coverMobileImgUploader"
              key="coverMobileImgUploader"
              uploadClass="upload-img-container"
              tip="建议尺寸：360 X 640"
              listType
              :showDelAction="true"
              :cropImg="true"
              :cropFixed="false"
              cropDialogTop="2vh"
              :cropDialogModal="false"
              :autoCropWidth="360"
              :autoCropHeight="640"
              cropperClass="cropper-bg-img-content"
              :autoUpload="false"
              @onSuccess="onCoverMobileUploadSuccess"
              @onClearFile="onCoverMobileClearLogoFile"
            />
          </el-form-item>
          <!-- <el-form-item label="背景图片">
            <vr-upload
            ref="coverBgImgUploader"
              uploadClass="upload-img-container upload-bg-img-container"
              tip="图片建议小于100k"
              listType
              :maxFileSize="200 * 1024"
              :showDelAction="true"
              :autoUpload="true"
              @onSuccess="onBgImgUploadSuccess"
              @onClearFile="onBgImgClearLogoFile"
            />
          </el-form-item>
          <el-form-item label="背景颜色">
            <el-color-picker
              v-model="coverForm.background_color"
              show-alpha
            ></el-color-picker>
          </el-form-item> -->
          <el-form-item label="进入方式">
            <el-radio-group v-model="coverForm.entry_mode" size="small">
              <el-radio-button label="auto">自动进入</el-radio-button>
              <el-radio-button label="manual">手动进入</el-radio-button>
            </el-radio-group>
          </el-form-item>
          <el-form-item size="large">
            <el-button type="primary" @click="onSaveBeginCover">保存</el-button>
          </el-form-item>
        </el-form>
      </el-tab-pane>
    </el-tabs>
  </el-dialog>
</template>
<script>
// eslint-disable-next-line no-unused-vars
import { getProductConfig, setProductConfig } from '@/api/vr'

const defaultStyleForm = {
  img: '',
  img_full: '',
  show_time: 2,
  use_intro_entrance: 0,
  intro_auto_rate: 1,
}
const defaultCoverForm = {
  pc_img: '',
  pc_img_full: '',
  mobile_img: '',
  mobile_img_full: '',
  entry_mode: 'manual',
  //   background_color: '#000000',
  //   background_img: '',
  //   background_img_full: '',
}
export default {
  name: 'BeginConfig',
  components: {
    VrUpload: () => import('@/components/VrUpload.vue'),
  },
  data() {
    return {
      dialogVisible: false,
      tabId: 'begin_style',
      styleForm: Object.assign({}, defaultStyleForm),
      coverForm: Object.assign({}, defaultCoverForm),
      formLabelWidth: '120px',
    }
  },
  props: {
    productId: null,
  },
  methods: {
    init() {
      this.getConfig()
      this.dialogVisible = true
    },
    getConfig() {
      return Promise.all([
        getProductConfig(this.productId, 'begin_style'),
        getProductConfig(this.productId, 'begin_cover'),
      ])
        .then((results) => {
          // results是一个包含两个请求结果的数组
          if (results[0] !== null) {
            this.styleForm = Object.assign({}, results[0].val)
            this.$refs.tipImgUploader.initFileList([
              {
                name: '开场提示',
                path: this.styleForm.img,
                url: this.styleForm.img_full,
              },
            ])
          }
          if (results[1] !== null) {
            this.coverForm = Object.assign({}, results[1].val)
            this.$refs.coverPcImgUploader.initFileList([
              {
                name: 'pc开场封面',
                path: this.coverForm.pc_img,
                url: this.coverForm.pc_img_full,
              },
            ])
            this.$refs.coverMobileImgUploader.initFileList([
              {
                name: '移动端开场封面',
                path: this.coverForm.mobile_img,
                url: this.coverForm.mobile_img_full,
              },
            ])
            // this.$refs.coverBgImgUploader.initFileList([{
            //     name: '背景图片',
            //     path: this.styleForm.background_img,
            //     url: this.styleForm.background_img_full
            // }])
          }
          return 'ok'
        })
        .catch((error) => {
          // 处理任何一个请求失败的情况
          console.error('Error:', error)
          throw new Error('fail')
        })
    },
    onBeforeClose() {
      this.clear()
      this.dialogVisible = false
      this.tabId = 'begin_style'
    },
    clear() {
      this.clearstyleForm()
      this.clearCoverForm()
    },
    clearstyleForm() {
      if (this.$refs.beginstyleForm) {
        this.$refs.beginstyleForm.resetFields()
      }
      //   this.$refs.tipImgUploader.clear()
      this.beginstyleForm = Object.assign({}, defaultStyleForm)
    },
    clearCoverForm() {
      if (this.$refs.beginCoverForm) {
        this.$refs.beginCoverForm.resetFields()
      }
      //   this.$refs.coverPcImgUploader.clear()
      //   this.$refs.coverMobileImgUploader.clear()
      this.beginCoverForm = Object.assign({}, defaultCoverForm)
    },
    onTipImgUploadSuccess(data) {
      this.styleForm.img = data.path
    },
    onTipImgClearLogoFile() {
      this.styleForm.img = ''
    },
    onCoverPcUploadSuccess(data) {
      this.coverForm.pc_img = data.path
    },
    onCoverPcClearLogoFile() {
      this.coverForm.pc_img = ''
    },
    onCoverMobileUploadSuccess(data) {
      this.coverForm.mobile_img = data.path
    },
    onCoverMobileClearLogoFile() {
      this.coverForm.mobile_img = ''
    },
    onBgImgUploadSuccess(data) {
      this.coverForm.background_img = data.path
    },
    onBgImgClearLogoFile() {
      this.coverForm.background_img = ''
    },
    onSaveAndCloseBeginTip() {
      return this.saveBeginTipConfig(true)
    },
    onSaveBeginTip() {
      return this.saveBeginTipConfig()
    },
    saveBeginTipConfig(close = false) {
      setProductConfig(this.productId, 'begin_style', {
        img: this.styleForm.img,
        show_time: this.styleForm.show_time,
        use_intro_entrance: this.styleForm.use_intro_entrance,
        intro_auto_rate: this.styleForm.intro_auto_rate,
      }).then(() => {
        this.$message.success('设置成功')
        if (close) {
          this.onBeforeClose()
        } else {
          this.clearstyleForm()
          this.tabId = 'begin_cover'
        }
      })
    },
    onSaveBeginCover() {
      setProductConfig(this.productId, 'begin_cover', {
        pc_img: this.coverForm.pc_img,
        mobile_img: this.coverForm.mobile_img,
        entry_mode: this.coverForm.entry_mode,
      }).then(() => {
        this.$message.success('设置成功')
        this.onBeforeClose()
      })
    },
  },
}
</script>
